    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['expense_number'] = Variable<String>(expenseNumber);
    if (!nullToAbsent || category != null) {
      map['category'] = Variable<String>(category);
    }
    map['amount'] = Variable<double>(amount);
    map['expense_date'] = Variable<DateTime>(expenseDate);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['is_packaging_expense'] = Variable<bool>(isPackagingExpense);
    if (!nullToAbsent || relatedPackagingRecordId != null) {
      map['related_packaging_record_id'] = Variable<String>(
        relatedPackagingRecordId,
      );
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  ExpensesCompanion toCompanion(bool nullToAbsent) {
    return ExpensesCompanion(
      id: Value(id),
      expenseNumber: Value(expenseNumber),
      category: category == null && nullToAbsent
          ? const Value.absent()
          : Value(category),
      amount: Value(amount),
      expenseDate: Value(expenseDate),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      isPackagingExpense: Value(isPackagingExpense),
      relatedPackagingRecordId: relatedPackagingRecordId == null && nullToAbsent
          ? const Value.absent()
          : Value(relatedPackagingRecordId),
      createdAt: Value(createdAt),
    );
  }

